Method.Source:
protected void updateBasedOnSource()
{
    next updateBasedOnSource();

    SalesLine returnSalesLine = this.parmSalesLine();

    // Only run for return order lines
    if (!returnSalesLine.salesTable().returnItem())
    {
        return;
    }

    // sourceCustInvoiceTrans is private — access via retrieveSource() which returns it as Common
    CustInvoiceTrans sourceTrans = this.retrieveSource() as CustInvoiceTrans;
    if (!sourceTrans || !sourceTrans.RecId)
    {
        return;
    }

    METSalesLine returnMETSalesLine = METSalesLine::find(returnSalesLine.RecId, true);
    if (!returnMETSalesLine)
    {
        return;
    }

    ttsbegin;
    returnMETSalesLine.InvoiceNumber      = sourceTrans.InvoiceId;
    returnMETSalesLine.InvoiceLineNumber  = sourceTrans.LineNum;   
    if (returnMETSalesLine.validateWrite())
    {
        returnMETSalesLine.update();
    }
    ttscommit;
}
